package com.ptraam.tracker;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;
public final class ExpensesActivity extends Activity{
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private Spinner trips;private EditText amount,note;private TextView message;private Button submit;private final ArrayList<String> ids=new ArrayList<>();private boolean busy;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(!Session.valid(this)){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_expenses);trips=findViewById(R.id.expense_trip);amount=findViewById(R.id.expense_amount);note=findViewById(R.id.expense_note);message=findViewById(R.id.expense_message);submit=findViewById(R.id.expense_submit);submit.setOnClickListener(v->submit());findViewById(R.id.expense_back).setOnClickListener(v->finish());load();}
 private void load(){call("/workforce/state",new JSONObject(),false);}private void submit(){if(busy||trips.getSelectedItemPosition()<0||trips.getSelectedItemPosition()>=ids.size()){message.setText("Choose one of your editable trips.");return;}double value;try{value=Double.parseDouble(amount.getText().toString());}catch(Exception e){message.setText("Enter a valid expense amount.");return;}try{call("/expenses/submit",new JSONObject().put("tripId",ids.get(trips.getSelectedItemPosition())).put("extra",value).put("note",note.getText().toString()),true);}catch(Exception e){message.setText("Check the expense.");}}
 private void call(String path,JSONObject body,boolean submitted){busy=true;submit.setEnabled(false);worker.execute(()->{try{JSONObject r=Api.post(this,path,body,true);runOnUiThread(()->{busy=false;submit.setEnabled(true);if(submitted){message.setText("Expense saved. Total reimbursement: INR "+r.optDouble("amount",0));load();return;}JSONArray rows=r.optJSONArray("trips");ids.clear();ArrayList<String> labels=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(!"Travelling".equals(x.optString("status"))&&!"Pending".equals(x.optString("status")))continue;ids.add(x.optString("id"));labels.add(new SimpleDateFormat("dd MMM yyyy",Locale.getDefault()).format(new Date(x.optLong("start")))+" · "+x.optString("status")+" · "+x.optString("id").substring(0,8));}trips.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));message.setText(labels.isEmpty()?"No editable trips available.":"");});}catch(Exception e){runOnUiThread(()->{busy=false;submit.setEnabled(true);message.setText(e.getMessage());});}});}@Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
